From Coq Require Import List String.
From Buri Require Import Wire Native.
Import ListNotations Native.Native.
Open Scope string_scope.
Definition equality_seal_text : string := "".
Definition equality_seal_nodes :=
 match Wire.decode_text equality_seal_text with
 | Some (Wire.Cons (Wire.Atom false "buri-constructor-native-1") (Wire.Cons tagged Wire.Nil)) =>
   match untag 500 tagged with Some root => elements root | _ => None end
 | _ => None end.
Definition equality_seal_decode := match equality_seal_nodes with
 | Some xs => definitions 500 (firstn 4 (skipn 0 xs)) | None => None end.
Definition equality_seal_program := Eval vm_compute in
 match equality_seal_decode with Some ds => ds | None => [] end.
Theorem equality_seal_exact : equality_seal_decode = Some equality_seal_program.
Proof. vm_compute. reflexivity. Qed.
Theorem equality_seal_names : map fst equality_seal_program = ["kl:buri.eq2-seal-definition";"kl:buri.eq2-seal-program";"kl:buri.eq2-seal-request";"kl:buri.make-sealed-eq2"].
Proof. vm_compute. reflexivity. Qed.
Theorem equality_seal_complete : match equality_seal_nodes with
 | Some xs => List.length xs = 4 | None => False end.
Proof. vm_compute; reflexivity. Qed.
Global Opaque equality_seal_text equality_seal_nodes equality_seal_decode.
